"""Binding HansePack article catalogue (human-written, not generated by the Factory).

The catalogue is the customer file `fixtures/HansePack_Katalog.json`, copied unchanged
(see `fixtures/SHA256SUMS`). Prices are integer cents per sales unit.
"""

from __future__ import annotations

import json
from pathlib import Path

CATALOG_FILE = Path(__file__).resolve().parents[1] / "fixtures" / "HansePack_Katalog.json"


def load_catalog(path: Path = CATALOG_FILE) -> dict[str, int]:
    """Return {sku: unit_price_cents} from the binding customer catalogue."""
    data = json.loads(path.read_text(encoding="utf-8"))
    return {item["sku"]: int(item["unit_price_cents"]) for item in data["products"]}
